package com.skillbridge;
import com.fasterxml.jackson.databind.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.security.core.Authentication;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasRole('ADMIN')") @Transactional
class AdminController {
 final WorkspaceService w;final JdbcTemplate db;AdminController(WorkspaceService w){this.w=w;db=w.db();}
 @GetMapping("/users") Object users(@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="")String role,@RequestParam(defaultValue="0")int page){return db.queryForList("SELECT id,name,email,role,enabled,verified,created_at FROM app_user WHERE (name ILIKE ? OR email ILIKE ?) AND (?='' OR role=?) ORDER BY id LIMIT 10 OFFSET ?","%"+q+"%","%"+q+"%",role,role,Math.max(0,page)*10);}
 @PatchMapping("/users/{id}") Object editUser(Authentication a,@PathVariable long id,@RequestBody JsonNode b){var actor=SecurityConfig.member(a);var rows=db.queryForList("SELECT id,role FROM app_user WHERE id=? FOR UPDATE",id);if(rows.isEmpty())throw ApiException.error(404,"User not found.");if(id==actor.id()&&(b.has("role")||b.has("enabled")&&!b.path("enabled").asBoolean()))throw ApiException.error(400,"Use another administrator to change your own access.");if(b.has("name"))db.update("UPDATE app_user SET name=? WHERE id=?",WorkspaceService.text(b,"name",2,80),id);if(b.has("role")){String role=WorkspaceService.text(b,"role",1,16);if(!List.of("LEARNER","MENTOR","ADMIN").contains(role))throw ApiException.error(400,"Choose a valid role.");db.update("UPDATE app_user SET role=? WHERE id=?",role,id);}if(b.has("enabled"))db.update("UPDATE app_user SET enabled=? WHERE id=?",b.path("enabled").asBoolean(),id);db.update("DELETE FROM auth_token WHERE user_id=?",id);w.audit(actor.id(),"user.update",String.valueOf(id),b);return Map.of("message","User updated; active sessions revoked.");}
 @GetMapping("/applications") Object applications(){return db.queryForList("SELECT a.*,u.email FROM mentor_application a JOIN app_user u ON u.id=a.user_id ORDER BY a.created_at DESC");}
 @PostMapping("/applications/decision") Object decision(Authentication a,@RequestBody JsonNode b){var actor=SecurityConfig.member(a);long id=b.path("applicationId").asLong();var apps=db.queryForList("SELECT * FROM mentor_application WHERE id=? FOR UPDATE",id);if(apps.isEmpty())throw ApiException.error(404,"Application not found.");String status=WorkspaceService.text(b,"status",1,40),decision=WorkspaceService.text(b,"decision",10,2000);if(!List.of("Approved","Rejected","More information requested").contains(status))throw ApiException.error(400,"Choose a valid decision.");var app=apps.get(0);long user=((Number)app.get("user_id")).longValue();var data=w.object(app.get("data").toString());db.update("UPDATE mentor_application SET status=?,decision=?,reviewed_by=?,reviewed_at=now() WHERE id=?",status,decision,actor.id(),id);if(status.equals("Approved")){db.update("UPDATE app_user SET role='MENTOR' WHERE id=? AND role<>'ADMIN'",user);db.update("INSERT INTO mentor_profile(user_id,name,expertise,bio,price,approved) VALUES(?,?,?,?,45,true) ON CONFLICT(user_id) DO UPDATE SET name=excluded.name,expertise=excluded.expertise,bio=excluded.bio,approved=true",user,data.path("name").asText(),data.path("expertise").asText(),data.path("experience").asText());}else db.update("UPDATE mentor_profile SET approved=false WHERE user_id=?",user);w.note(user,"Your mentor application: "+status+". "+decision);w.audit(actor.id(),"mentor.review",String.valueOf(id),Map.of("status",status,"decision",decision));return w.state(actor);}
 @GetMapping("/content") Object content(){return db.queryForList("SELECT * FROM content ORDER BY id");}
 @PostMapping("/content") Object create(Authentication a,@RequestBody JsonNode b){String type=WorkspaceService.text(b,"type",1,20),title=WorkspaceService.text(b,"title",2,150),description=WorkspaceService.text(b,"description",1,10000);if(!List.of("Course","Project","Lesson","Category","Skill").contains(type))throw ApiException.error(400,"Choose a valid content type.");Long id=db.queryForObject("INSERT INTO content(kind,title,description,data) VALUES(?,?,?,?::jsonb) RETURNING id",Long.class,type,title,description,w.encode(b));w.audit(SecurityConfig.member(a).id(),"content.create",String.valueOf(id),Map.of("type",type));return Map.of("id",id,"status","Draft");}
 @PatchMapping("/content/{id}") Object editContent(Authentication a,@PathVariable long id,@RequestBody JsonNode b){var rows=db.queryForList("SELECT * FROM content WHERE id=? FOR UPDATE",id);if(rows.isEmpty())throw ApiException.error(404,"Content not found.");var old=rows.get(0);if(b.has("status")){String status=b.path("status").asText();if(!List.of("Draft","Published","Archived").contains(status))throw ApiException.error(400,"Invalid content status.");if(status.equals("Published")&&List.of("Course","Project").contains(old.get("kind"))){var data=b.has("data")?b.get("data"):w.object(old.get("data").toString());if(!data.has("id")||!data.has("skills")||!data.has("title"))throw ApiException.error(400,"Published courses and projects require id, title, and skills in data.");if(old.get("kind").equals("Course")&&!data.path("lessons").isArray())throw ApiException.error(400,"Add course lessons before publication.");}db.update("UPDATE content SET status=? WHERE id=?",status,id);}if(b.has("title"))db.update("UPDATE content SET title=? WHERE id=?",WorkspaceService.text(b,"title",2,150),id);if(b.has("data"))db.update("UPDATE content SET data=?::jsonb WHERE id=?",w.encode(b.get("data")),id);w.audit(SecurityConfig.member(a).id(),"content.update",String.valueOf(id),b);return Map.of("message","Content updated.");}
 @GetMapping("/bookings") Object bookings(){return db.queryForList("SELECT b.*,p.status AS payment_status,p.provider FROM booking b JOIN payment p ON p.booking_id=b.id ORDER BY b.created_at DESC LIMIT 100");}
 @GetMapping("/audit") Object audit(){return db.queryForList("SELECT * FROM audit_event ORDER BY id DESC LIMIT 100");}
 @GetMapping("/reports") Object reports(){return db.queryForList("SELECT * FROM report ORDER BY id DESC LIMIT 100");}
 @PatchMapping("/reports/{id}") Object report(Authentication a,@PathVariable long id,@RequestBody JsonNode b){String decision=WorkspaceService.text(b,"decision",10,2000);if(db.update("UPDATE report SET status='Resolved',decision=?,reviewed_by=? WHERE id=?",decision,SecurityConfig.member(a).id(),id)==0)throw ApiException.error(404,"Report not found.");w.audit(SecurityConfig.member(a).id(),"report.resolve",String.valueOf(id),b);return Map.of("message","Report resolved.");}
 @GetMapping("/overview") Object overview(@RequestParam(defaultValue="30")int days){days=Math.min(365,Math.max(1,days));return Map.of("learners",db.queryForObject("SELECT count(*) FROM app_user WHERE role='LEARNER'",Long.class),"mentors",db.queryForObject("SELECT count(*) FROM mentor_profile WHERE approved",Long.class),"pendingApplications",db.queryForObject("SELECT count(*) FROM mentor_application WHERE status='Pending'",Long.class),"bookings",db.queryForObject("SELECT count(*) FROM booking WHERE created_at>now()-make_interval(days=>?)",Long.class,days),"testRevenue",db.queryForObject("SELECT coalesce(sum(amount),0) FROM payment WHERE status='test_paid' AND created_at>now()-make_interval(days=>?)",Double.class,days),"paymentMode","internal_development_sandbox");}
}
